function updateContext(){if($('#selected-refs'))$('#selected-refs').innerHTML=refsHTML();if($('#context-results'))$('#context-results').innerHTML=candidatesHTML();if($('#context-count'))$('#context-count').textContent=selectedRefs.length;invalidatePreview()}
