async function loadMessages(){if(page!=='chat')return;const r=sessionId?await api('/api/messages?session_id='+encodeURIComponent(sessionId)):{messages:[]};lastMessages=r.messages;const box=$('#messages'),atBottom=box.scrollHeight-box.scrollTop-box.clientHeight<80;box.innerHTML=r.messages.map(m=>`<article class="message ${m.role==='user'?'user':'assistant'}"><label>${m.role==='user'?'我':'Codex'} · ${time(m.created_at)}</label><div class="markdown">${markdown(m.text)}</div>${m.role==='assistant'?replyEvidence(m)+`<div class="actions">${btn('保存这条结论','save-message:'+m.id,'linkbtn')}${btn('形成目标或行动 →','record:message:'+m.id,'linkbtn')}</div>`:''}</article>`).join('')||`<div class="chatwelcome"><div class="eyebrow">把真实处境带进来</div><h2>从一个具体困惑，聊到一个可做的下一步。</h2><p>右侧可以查找个人材料与顾问原文。发送前，你能看到这一轮会带上什么。</p>${domains().slice(0,3).map(d=>`<button class="suggestion" data-action="domain-question:${esc(d.id)}">${esc(d.plan_draft?.title||d.title)} <span>↗</span></button>`).join('')}</div>`;if(atBottom)box.scrollTop=box.scrollHeight;const job=S.jobs.find(j=>j.session_id===sessionId);$('#job-state').innerHTML=job?`<div class="jobstate ${['failed','interrupted'].includes(job.status)?'error':''}">${statuses[job.status]||job.status} ${esc(job.error||'')}${['queued','running'].includes(job.status)?btn('停止','cancel:'+job.id,'small'):['failed','interrupted','cancelled'].includes(job.status)?btn('恢复问题重试','retry:'+job.id,'small'):''}</div>`:'';if(job&&['queued','running','cancelling'].includes(job.status))poll=setTimeout(async()=>{try{await refresh(false);await loadMessages()}catch(e){toast(e.message)}},1500)}
function replyEvidence(m){const c=m.reply_context;if(!c)return '<details class="reply-evidence"><summary>当轮依据与发送内容</summary><p class="subtle">这条历史回复没有保存可回读的发送快照，不用当前资料替代历史依据。</p></details>';return `<details class="reply-evidence"><summary>当轮依据与发送内容 · ${list(c.contexts).length} 份资料</summary><p class="subtle">这是当时实际发送的快照。右侧资料属于下一轮选择，修改后不会改变此处留底。</p>${c.message?'<div class="context-card"><strong>当轮问题</strong><pre>'+esc(c.message)+'</pre></div>':''}<p class="subtle">当轮携带 ${Number(c.history_count)||0} 条历史</p>${list(c.contexts).map(r=>`<details><summary>${esc(r.title)} · ${esc(r.kind||'资料')}${r.truncated?' · 截取内容':''}</summary><pre class="reading">${esc(r.text)}</pre><small>实际包含 ${Number(r.included_characters)||String(r.text||'').length} 字符</small></details>`).join('')}${list(c.history).length?`<details><summary>当轮历史正文</summary><pre class="reading">${esc(c.history.map(x=>x.role+'：'+x.text).join('\n\n'))}</pre></details>`:''}<details><summary>快照标识</summary><small>预览 ${esc(c.preview_id||'')}<br>内容校验 ${esc(c.context_hash||'')}</small></details></details>`}
function domainDetail(d){open(`<div class="eyebrow">${esc(d.title)} · 从资料整理的方案</div><h2>${esc(d.plan_draft?.title||d.title)}</h2><p>${esc(d.plan_draft?.why||d.priority_reason)}</p><div class="muted-box">${esc(plain(d.plan_draft?.approach)||d.priority_reason)}</div><h3 class="subsection-title">这些判断，来自你的材料</h3>${list(d.known_facts).map(f=>`<div class="evidence-item"><p>${esc(f.text)}</p><small>${esc(f.date||'日期见原文')} · ${esc(f.evidence_type||'材料记录')} · ${esc(f.locator||'')}</small><div>${btn('回读：'+esc(sourceTitle(f.source_id)),'read:source:'+String(f.source_id||'').replace(/^source:/,''),'linkbtn')}</div></div>`).join('')}${list(d.constraints).length?`<h3>需要一起考虑的现实条件</h3><ul>${list(d.constraints).map(x=>'<li>'+esc(plain(x))+'</li>').join('')}</ul>`:''}${list(d.unknowns).length?`<details><summary>还需要补充 ${list(d.unknowns).length} 项信息</summary><ul>${list(d.unknowns).map(x=>'<li>'+esc(plain(x))+'</li>').join('')}</ul></details>`:''}<h3>可选的起步行动</h3>${list(d.actions).map(a=>`<div class="week-item"><strong>${esc(a.title)}</strong><p>${list(a.steps).map(plain).map(esc).join(' → ')}</p><small>完成依据：${esc(plain(a.completion_evidence)||'留下实际结果')}</small></div>`).join('')}<p class="subtle">回看时机：${esc(d.plan_draft?.review_trigger||'行动完成，或现实条件改变时')}</p><div class="actions">${btn('采用并调整这套方案','adopt:'+d.id,'primary')}${btn('先和顾问讨论','domain-chat:'+d.id)}${btn('回读完整方案','read:plan:'+d.id,'linkbtn')}</div>`,true)}
function adoptionForm(d,onlyActionId){adoptDomain=d;const old=activeGoals().find(g=>g.domain_id===d.id);if(old){goalForm(old);return}const steps=list(d.actions).map(a=>({text:a.title,criterion:plain(a.completion_evidence)||'',due:a.due||''}));open(`<div class="eyebrow">${esc(d.title)} · 由你决定开始</div><h2>把整理好的方案，变成自己的计划。</h2><p class="subtle">内容已按你的材料填写。采用后保存为工作台执行目标；原目标台账保持只读，采用状态不会自动写回。</p><div class="field"><label for="adopt-title">这个阶段要做到什么</label><input id="adopt-title" value="${esc(d.plan_draft?.title||d.title)}"></div><div class="field"><label for="adopt-why">为什么值得做</label><textarea id="adopt-why">${esc(d.plan_draft?.why||d.priority_reason)}</textarea></div><div class="formrow"><div class="field"><label for="adopt-priority">当前优先级</label><select id="adopt-priority"><option value="1">优先推进</option><option value="2" selected>稳步推进</option><option value="3">有余力时推进</option></select></div><div class="field"><label for="adopt-due">阶段回看日期（可留空）</label><input type="date" id="adopt-due"></div></div><h3>起步行动，可以删减</h3><div id="adopt-actions">${steps.map((s,i)=>`<div class="evidence-item"><label class="step"><input type="checkbox" data-adopt-check="${i}" ${!onlyActionId||list(d.actions)[i]?.id===onlyActionId?'checked':''}>采用这一步</label><input data-adopt-text="${i}" aria-label="行动 ${i+1}" value="${esc(s.text)}"><div class="field"><label>怎样算做到</label><input data-adopt-criterion="${i}" value="${esc(s.criterion)}"></div><label class="subtle">准备在哪天做</label><input type="date" data-adopt-due="${i}" value="${esc(s.due)}"></div>`).join('')}</div><div class="actions">${btn('确认采用，加入我的计划','save-adopt','primary')}${btn('暂时不采用','close','quiet')}</div>`,true)}
function editedSteps(lines,oldSteps){
 const used=new Set(),matches=lines.map(text=>{const found=oldSteps.find(x=>x.text===text&&!used.has(x.id));if(found)used.add(found.id);return found});
 return lines.map((text,i)=>{if(matches[i])return {...matches[i],text};const prior=oldSteps[i];if(prior&&!used.has(prior.id)){used.add(prior.id);return {...prior,text}}return {text,done:false}});
}
function goalForm(g){g=g||{status:'draft',steps:[],title:'',why:'',due:'',domain:'个人目标'};open(`<div class="eyebrow">目标与计划</div><h2>${g.id?'调整目标，保留过程':'自定一个当前目标'}</h2><div class="field"><label for="g-title">我想实现什么</label><input id="g-title" value="${esc(g.title)}"></div><div class="field"><label for="g-why">为什么值得做</label><textarea id="g-why">${esc(g.why)}</textarea></div><div class="formrow"><div class="field"><label for="g-domain">所属方向</label><select id="g-domain"><option value="">个人自定</option>${domains().map(d=>`<option value="${esc(d.id)}" ${g.domain_id===d.id?'selected':''}>${esc(d.title)}</option>`).join('')}</select></div><div class="field"><label for="g-due">目标日期</label><input type="date" id="g-due" value="${esc(g.due||'')}"></div></div><div class="formrow"><div class="field"><label for="g-status">当前状态</label><select id="g-status">${['draft','active','paused','done','archived'].map(s=>`<option value="${s}" ${g.status===s?'selected':''}>${statuses[s]}</option>`).join('')}</select></div><div class="field"><label for="g-priority">当前优先级</label><select id="g-priority">${[[1,'优先推进'],[2,'稳步推进'],[3,'有余力时推进']].map(([v,t])=>`<option value="${v}" ${(g.priority||2)===v?'selected':''}>${t}</option>`).join('')}</select></div></div><div class="field"><label for="g-parent">连接一个长期目标</label><select id="g-parent"><option value="">独立方向</option>${S.goals.filter(x=>x.id!==g.id).map(x=>`<option value="${esc(x.id)}" ${g.parent_id===x.id?'selected':''}>${esc(x.title)}</option>`).join('')}</select></div><div class="field"><label for="g-steps">接下来做什么（每行一个行动）</label><small>修改原行动标题会保留结果；新增行动请另起一行。</small><textarea id="g-steps">${esc(list(g.steps).map(s=>s.text).join('\n'))}</textarea></div><div class="field"><label for="g-evidence">实际结果与证据（完成目标时填写）</label><textarea id="g-evidence">${esc(g.evidence||'')}</textarea></div>${recordOrigin(g.origin_id)}${g.source_snapshot?'<details><summary>方案来源与采用记录</summary><pre class="reading">'+esc(JSON.stringify(g.source_snapshot,null,2))+'</pre><p class="subtle">保存为工作台执行目标；原目标台账保持只读，采用状态未写回原台账。</p></details>':''}${btn('保存目标','save-goal:'+(g.id||'new'),'primary')}`)}
function noteForm(n){open(`<div class="eyebrow">保留原话，再继续整理</div><h2>${n?.id?'编辑这条记录':'留下一条记录'}</h2><div class="field"><label for="n-title">标题</label><input id="n-title" value="${esc(n?.title||'')}"></div><div class="field"><label for="n-body">内容</label><textarea id="n-body" class="note-editor">${esc(n?.body||'')}</textarea></div><div class="formrow"><div class="field"><label for="n-kind">记录类型</label><select id="n-kind">${[['idea','想法'],['learning','学习理解'],['review','复盘'],['conversation','对话结论']].map(([k,t])=>`<option value="${k}" ${n?.kind===k?'selected':''}>${t}</option>`).join('')}</select></div><div class="field"><label for="n-goal">关联目标</label><select id="n-goal"><option value="">暂不关联</option>${S.goals.map(g=>`<option value="${esc(g.id)}" ${n?.goal_id===g.id?'selected':''}>${esc(g.title)}</option>`).join('')}</select></div></div><div class="actions">${btn('保存记录','save-note:'+(n?.id||'new'),'primary')}${btn('保存并入知识库','save-index-note:'+(n?.id||'new'))}</div>`)}
function recordDraft(body,title){const text=String(body||'').replace(/\r/g,''),parts=text.split('\n');const next=text.match(/(?:^|\n)#{1,6}\s*(?:下一步|行动计划|行动建议|具体行动|接下来)[^\n]*\n([\s\S]*?)(?=\n#{1,6}\s|$)/);const scope=(next?.[1]||text).split('\n').map(s=>s.trim()).filter(Boolean);const clean=s=>s.replace(/^#{1,6}\s*/,'').replace(/^[-*+]\s+|^\d+[.)、]\s*/,'').replace(/\*\*/g,'').trim();let steps=scope.filter(s=>/^[-*+]\s+|^\d+[.)、]\s*/.test(s)).map(clean);if(!next)steps=steps.filter(s=>/(整理|选择|列出|检查|确认|记录|完成|阅读|练习|写下|回看|核对|尝试|比较|做一次|找出|开始|制定|联系|保存|安排|停止|复盘|检验|收集|更新)/.test(s));if(next&&!steps.length)steps=scope.filter(s=>!/^#/.test(s)).map(clean);steps=steps.filter(s=>s&&s!=='暂未记录').slice(0,5);const first=steps[0]||parts.map(clean).find(s=>s&&s!=='暂未记录')||'';return {title:clip(next?first:title||first,90),why:clip(parts.map(clean).filter(s=>s&&!/^(主线|卡点|学什么|实际结果|下一步)$/.test(s)).join('；'),260),steps}}
function recordForm(sourceId){recordSource=sourceId;const [kind,id]=sourceId.split(':');const src=kind==='message'?lastMessages.find(m=>m.id===id):S.notes.find(n=>n.id===id);const body=src?.text||src?.body||'',draft=recordDraft(body,src?.title);open(`<div class="eyebrow">从讨论与经历，走向行动</div><h2>把值得做的部分，留下来推进。</h2><p class="notice">按原文整理的可编辑草稿，请核对取舍；尚未自动承诺。${draft.steps.length?'':'原文未识别到明确行动，已保留结论，请补充你愿意推进的一步。'}</p><details><summary>回看这条${kind==='message'?'回复':'记录'}</summary><div class="markdown">${markdown(body)}</div></details><div class="field"><label for="record-mode">这次怎样推进</label><select id="record-mode"><option value="goal">形成一个新目标</option>${S.goals.length?'<option value="action">添加到已有目标，作为下一步行动</option>':''}</select></div><div class="field" id="record-existing" hidden><label for="record-goal">关联目标</label><select id="record-goal">${S.goals.map(g=>`<option value="${esc(g.id)}">${esc(g.title)}</option>`).join('')}</select></div><div class="field"><label for="record-title">我愿意推进的这件事</label><input id="record-title" value="${esc(draft.title)}" placeholder="从原文中取舍，用一句话说清楚"></div><div class="field"><label for="record-why">意义 / 完成依据</label><textarea id="record-why" placeholder="怎样才算真的有进展？">${esc(draft.why)}</textarea></div><div id="record-goal-fields"><div class="field"><label for="record-steps">起步行动（每行一个）</label><textarea id="record-steps">${esc(draft.steps.join('\n'))}</textarea></div><div class="field"><label for="record-domain">所属方向</label><select id="record-domain"><option value="">个人自定</option>${domains().map(d=>`<option value="${esc(d.id)}">${esc(d.title)}</option>`).join('')}</select></div></div><div class="formrow"><div class="field"><label for="record-due">准备在哪天做（可留空）</label><input type="date" id="record-due"></div><div class="field"><label for="record-priority">当前优先级</label><select id="record-priority"><option value="1">优先推进</option><option value="2" selected>稳步推进</option><option value="3">有余力时推进</option></select></div></div>${btn('确认，加入我的计划','save-record','primary')}<p class="subtle">这次确认会留下来源关联；不会把整条回复自动当作承诺。</p>`,true)}
async function showRead(id){reading=await api('/api/read?id='+encodeURIComponent(id));open(`<div class="eyebrow">${esc(reading.kind||'原始材料')}</div><h2>${esc(reading.title)}</h2><p class="subtle">${esc(reading.source||'')}${reading.truncated?' · 当前显示内容已截断':''}</p><div class="markdown">${markdown(reading.text)}</div><div class="actions actions-spaced">${btn('选入本轮对话','read-chat','primary')}${btn('关闭','close')}</div>`,true)}
async function requestContext(question){if(!question.trim())throw Error('先说出一个具体问题，我再帮你找资料。');const r=await api('/api/context',{question,domain_id:domain(selectedDomain)?selectedDomain:undefined});contextCandidates=r.candidates||[];contextWarnings=r.warnings||[];if(!contextCandidates.length&&!contextWarnings.length)contextWarnings=['没有找到足够相关的资料。可以换一个具体词，或直接讨论。'];for(const id of r.suggested_ids||[]){const c=contextCandidates.find(x=>x.id===id);if(c&&selectedRefs.length<4)addRef(c)}updateContext();return r}
function draftId(body){let x;try{x=JSON.parse(localStorage.getItem('growth-save-request')||'null')}catch{}if(!x||x.body!==body){x={body,id:crypto.randomUUID()};localStorage.setItem('growth-save-request',JSON.stringify(x))}return x.id}
async function watchIndex(){for(let i=0;i<20;i++){await new Promise(r=>setTimeout(r,1500));await refresh(false);if(!S.notes.some(n=>n.index_state==='indexing')){if(page==='notes')await draw();return}}}
async function action(a){const [cmd,...rest]=a.split(':'),id=rest.join(':');
if(cmd==='page')await navigate(id);
else if(cmd==='close')close();
else if(cmd==='quick-note'){noteSeed=null;noteForm(null)}
else if(cmd==='domain')domainDetail(domain(id));
else if(cmd==='filter-domain'){document.querySelectorAll('.filters button').forEach(b=>b.classList.toggle('selected',b.dataset.action==='filter-domain:'+id));$('#domain-grid').innerHTML=(id?[domain(id)]:domains()).filter(Boolean).map(domainCard).join('')}
else if(cmd==='adopt'){const [did,aid]=id.split(':');adoptionForm(domain(did),aid)}
else if(cmd==='save-adopt'){const steps=[...document.querySelectorAll('[data-adopt-check]')].filter(x=>x.checked).map(x=>{const i=x.dataset.adoptCheck,original=list(adoptDomain.actions)[Number(i)];return {plan_action_id:original?.id,canonical_action_ref:original?.canonical_action_ref||'',text:$(`[data-adopt-text="${i}"]`).value,criterion:$(`[data-adopt-criterion="${i}"]`).value,due:$(`[data-adopt-due="${i}"]`).value,done:false}});await api('/api/adopt',{domain_id:adoptDomain.id,title:$('#adopt-title').value,why:$('#adopt-why').value,priority:Number($('#adopt-priority').value),due:$('#adopt-due').value,steps});close();page='goals';await refresh();toast('已采用，接下来按你的节奏推进。')}
else if(cmd==='domain-chat'||cmd==='domain-question'){const d=domain(id);selectedDomain=d.id;localStorage.setItem('growth-chat-draft',`请结合我的资料和顾问方法，帮我讨论「${d.plan_draft?.title||d.title}」。\n${d.plan_draft?.first_question||'先识别当前最关键的卡点，再一起取舍一个能验证的下一步。'}`);close();page='chat';await draw();await requestContext($('#chat-text').value)}
else if(cmd==='panorama-discuss'){const p=S.plan?.life_panorama,m=p?.mastery;if(!m)throw Error('尚未接入近期专精方法');selectedDomain='';selectedRefs=[];sessionId='';for(const sid of [...new Set([...list(m.source_id),...list(list(p.route)[0]?.source_ids)])].filter(Boolean).slice(0,4))addRef({id:'source:'+String(sid).replace(/^source:/,''),title:sourceTitle(sid)});localStorage.setItem('growth-chat-draft',`请按我已有的「${m.title||'让我伟大'}」方法，结合当前材料，复盘近期工作如何更专精。\n${list(m.steps).map((x,i)=>`${i+1}. ${x.title}：${x.description}`).join('\n')}\n请先区分本人意愿、当前事实、历史记录和待验证判断。缺少当前成果证据时写明未知，不复用旧进度或收入数字，不自动替我承诺新的行动。\n${m.boundary||''}`);close();page='chat';await draw()}
else if(cmd==='goal')goalForm(S.goals.find(g=>g.id===id));
else if(cmd==='save-goal'){const old=S.goals.find(g=>g.id===id),lines=$('#g-steps').value.split('\n').map(x=>x.trim()).filter(Boolean),did=$('#g-domain').value;await api('/api/goals',{...old,title:$('#g-title').value,why:$('#g-why').value,parent_id:$('#g-parent').value,domain_id:did,domain:domain(did)?.title||'个人自定',due:$('#g-due').value,status:$('#g-status').value,priority:Number($('#g-priority').value),evidence:$('#g-evidence').value,steps:editedSteps(lines,old?.steps||[])});close();await refresh();toast('目标已保存。')}
else if(cmd==='step'){const [gid,sid]=id.split(':'),s=S.goals.find(g=>g.id===gid).steps.find(s=>s.id===sid);open(`<div class="eyebrow">一个具体行动</div><h2>${esc(s.text)}</h2><div class="field"><label for="step-due">准备在哪天做</label><input type="date" id="step-due" value="${esc(s.due||'')}"></div><div class="field"><label for="step-criterion">怎样算做到了</label><textarea id="step-criterion">${esc(s.criterion||'')}</textarea></div><div class="field"><label for="step-outcome">实际结果或证据</label><textarea id="step-outcome">${esc(s.outcome||'')}</textarea></div><label class="step"><input id="step-done" type="checkbox" ${s.done?'checked':''}>这一步已经完成</label>${btn('保存行动安排','save-step:'+id,'primary')}`)}
else if(cmd==='save-step'){const [gid,sid]=id.split(':'),g=structuredClone(S.goals.find(g=>g.id===gid)),s=g.steps.find(s=>s.id===sid);Object.assign(s,{due:$('#step-due').value,criterion:$('#step-criterion').value,outcome:$('#step-outcome').value,done:$('#step-done').checked});await api('/api/goals',g);close();await refresh();toast('行动和结果已保存。')}
else if(cmd==='discuss-goal'){const g=S.goals.find(g=>g.id===id);selectedDomain=g.domain_id||'';localStorage.setItem('growth-chat-draft',`我想讨论正在推进的目标：${g.title}\n请先帮我找出当前卡点，再讨论下一步。`);close();page='chat';await draw();$('#include-goals').checked=true;await requestContext($('#chat-text').value)}
else if(cmd==='capture-save'||cmd==='capture-index'){const b=$('#capture').value;if(!b.trim())throw Error('先留下一句想法。');await api('/api/notes',{body:b,kind:'idea',index:cmd==='capture-index',request_id:draftId(b)});localStorage.removeItem('growth-draft');localStorage.removeItem('growth-save-request');await refresh();toast(cmd==='capture-index'?'想法已保存，正在并入知识库。':'想法已保存。');if(cmd==='capture-index')watchIndex().catch(e=>toast(e.message))}
else if(cmd==='capture-chat'){localStorage.setItem('growth-chat-draft',$('#capture').value);await navigate('chat')}
else if(cmd==='toggle-archive'){showArchived=!showArchived;await draw()}
else if(cmd==='archive'){const n=S.notes.find(n=>n.id===id);await api('/api/note/archive',{id,archived:!n.archived});await refresh();toast(n.archived?'记录已恢复。':'已归档，原文与版本仍然保留。')}
else if(cmd==='note'){noteSeed=null;noteForm(S.notes.find(n=>n.id===id))}
else if(cmd==='save-note'||cmd==='save-index-note'){const old=S.notes.find(n=>n.id===id);await api('/api/notes',{...old,...(!old?noteSeed||{}:{}),title:$('#n-title').value,body:$('#n-body').value,kind:$('#n-kind').value,goal_id:$('#n-goal').value,index:cmd==='save-index-note',request_id:!old?draftId($('#n-body').value):undefined});close();noteSeed=null;await refresh();toast(cmd==='save-index-note'?'记录已保存，正在入库。':'记录已保存。');if(cmd==='save-index-note')watchIndex().catch(e=>toast(e.message))}
else if(cmd==='index'){await api('/api/index',{id});await refresh();toast('正在并入知识库，完成后更新状态。');watchIndex().catch(e=>toast(e.message))}
else if(cmd==='versions'){const r=await api('/api/versions?id='+encodeURIComponent(id));open('<h2>这条记录的变化</h2>'+r.versions.map(v=>`<details><summary>版本 ${v.rev} · ${time(v.data.updated_at)}</summary><pre class="reading">${esc(v.data.body||JSON.stringify(v.data,null,2))}</pre></details>`).join(''))}
else if(cmd==='note-chat'){const n=S.notes.find(n=>n.id===id);addRef({id:'note:'+id,title:n.title});localStorage.setItem('growth-chat-draft','我想接着这条记录讨论：'+n.title);await navigate('chat')}
else if(cmd==='review'){selectedDomain=id;await navigate('review')}
else if(cmd==='save-review'||cmd==='save-review-action'||cmd==='save-review-index'){const fields=['main','obstacle','learn','result','next'],values=Object.fromEntries(fields.map(k=>[k,$('#review-'+k).value.trim()]));if(!values.main||!values.result)throw Error('请至少写下当前主线和真实结果；尚未行动也可以如实记录。');const body=[['主线',values.main],['卡点',values.obstacle],['学什么',values.learn],['实际结果',values.result],['下一步',values.next]].map(([h,t])=>'## '+h+'\n'+(t||'暂未记录')).join('\n\n');const n=await api('/api/notes',{title:S.date+' · '+clip(values.main,45),body,kind:'review',goal_id:$('#review-goal').value,index:cmd==='save-review-index',request_id:draftId(body)});localStorage.removeItem('growth-review-draft');await refresh(false);if(cmd==='save-review-action'){recordForm('note:'+n.id);$('#record-title').value=values.next||values.main;if($('#record-mode')&&$('#review-goal')?.value){$('#record-mode').value='action';$('#record-goal').value=$('#review-goal').value;toggleRecordMode()}}else{page='notes';await draw()}toast('复盘已保存。');if(cmd==='save-review-index')watchIndex().catch(e=>toast(e.message))}
else if(cmd==='method'){const m=list(S.methods).find(m=>m.id===id);if(m)open(`<div class="eyebrow">本项目登记的方法 · ${esc(m.id)}</div><h2>${esc(m.title)}</h2><div class="markdown"><ol>${list(m.steps).map(t=>'<li>'+esc(plain(t))+'</li>').join('')}</ol></div><h3>留下什么结果</h3><ul>${list(m.outputs).map(t=>'<li>'+esc(plain(t))+'</li>').join('')}</ul><div class="actions">${list(m.advisor_slugs).map(slug=>btn('阅读 '+esc(advisor(slug)?.title||slug),'advisor:'+slug,'small')).join('')}</div><details><summary>方法来源与说明</summary>${list(m.source_urls).map(u=>'<p>'+link(u,'来源原文')+'</p>').join('')}<p class="subtle">${esc(m.license_basis||'')}</p></details>`,true)}
else if(cmd==='library-domain'){selectedDomain=id;advisorQuery='';advisorCategory='';await draw()}
else if(cmd==='library-all'){selectedDomain='';advisorQuery='';advisorCategory='';await draw()}
else if(cmd==='advisor')await enterAdvisor(id);
else if(cmd==='resume'){const l=S.learning.find(l=>l.id===id);await enterAdvisor(l.advisor,l.file_id)}
else if(cmd==='reader-file'){reading=await api('/api/read?id='+encodeURIComponent(id));await renderReader();window.scrollTo({top:0,behavior:'instant'})}
else if(cmd==='learning-save'){const insight=$('#learning-insight').value;if(id==='reading'&&!$('#learning-position').dataset.changed){const body=$('.reader-main'),p=Math.round(Math.max(0,Math.min(1,(window.scrollY-body.offsetTop)/Math.max(1,body.offsetHeight-innerHeight*.8)))*100);$('#learning-position').value=p;$('#position-value').textContent=p+'%'}if(id==='practiced'&&!insight.trim())throw Error('写下实际运用的结果，再记录为已实践。');await api('/api/learning',{advisor:readerSlug,file_id:reading.id,status:id,insight,goal_id:$('#learning-goal').value,position:id==='read'||id==='practiced'?100:Number($('#learning-position').value)});await refresh(false);toast(id==='reading'?'阅读位置和理解已保存，下次可以继续。':id==='read'?'已记录读完；有用的部分，可以继续落成行动。':'实践结果已保存。')}
else if(cmd==='learning-note'){noteSeed={kind:'learning',source:reading.id,title:'关于'+readerInfo.title+'的理解',body:$('#learning-insight').value,goal_id:$('#learning-goal').value};noteForm(noteSeed)}
else if(cmd==='reader-chat'){addRef(reading);const insight=$('#learning-insight')?.value;if(insight)localStorage.setItem('growth-chat-draft',`刚读了「${reading.title}」，我的理解是：\n${insight}\n请帮我结合实际处境，讨论如何运用。`);await navigate('chat')}
else if(cmd==='learning-history'){open('<div class="eyebrow">真实阅读与运用记录</div><h2>我的学习足迹</h2>'+S.learning.map(l=>`<article class="note"><div class="row spread"><h3>${esc(advisor(l.advisor)?.title||l.advisor)}</h3>${tag(statuses[l.status]||l.status)}</div><small>${time(l.updated_at||l.read_at)} · 阅读位置 ${Number(l.position)||0}%</small><p>${esc(l.insight||'还没有写下理解。')}</p>${btn('继续这份原文','resume:'+l.id,'linkbtn')}</article>`).join(''))}
else if(cmd==='read')await showRead(id);
else if(cmd==='read-chat'){addRef(reading);close();if(page!=='chat')await navigate('chat');else updateContext()}
else if(cmd==='select-ref'){const c=contextCandidates.find(r=>r.id===id);if(c)addRef(c);updateContext()}
else if(cmd==='remove-ref'){selectedRefs=selectedRefs.filter(r=>r.id!==id);updateContext()}
else if(cmd==='context-search'){const q=$('#context-query').value.trim();if(!q)throw Error('先输入一个关键词。');const r=await api('/api/search?q='+encodeURIComponent(q));contextCandidates=r.results||[];contextWarnings=contextCandidates.length?[]:['没有匹配这个词，换一个更具体的关键词试试。'];updateContext()}
else if(cmd==='recommend-context'){await requestContext($('#chat-text').value);toast(contextCandidates.length?'相关资料已在右侧列出。你可以回读、移除，再预览发送。':'这次没有找到相关资料，可以换一个词继续查找。')}
else if(cmd==='quote-source'){const q=S.quote;if(!q)return;open(`<div class="eyebrow">每日提醒 · 出处</div><h2>${esc(q.advisor)}</h2>${tag(q.type)}<blockquote>${esc(q.text)}</blockquote><p>${esc(q.original||'原文请查看来源')}</p><p class="subtle">${esc(q.source_locator||'')}</p><p>${link(q.source_url,'查看原始来源')}</p><p class="subtle">行动思考问题由工作台撰写，不是顾问原话。</p>`)}
else if(cmd==='quote-next'){S.quote=await api('/api/quote?offset='+ ++quoteOffset);await draw()}
else if(cmd==='quote-chat'){const q=S.quote;localStorage.setItem('growth-chat-draft',`今天的提醒是「${q.text}」，${q.advisor}，${q.type}。来源：${q.source_url}\n请结合我的处境，帮我把这个提醒变成一个适合今天的小行动。`);await navigate('chat')}
else if(cmd==='new-chat'){sessionId='';selectedRefs=[];contextCandidates=[];contextWarnings=[];await draw()}
else if(cmd==='session'){sessionId=id;await draw()}
else if(cmd==='preview'){const r=await api('/api/chat/preview',{message:$('#chat-text').value,session_id:sessionId||null,refs:selectedRefs.map(r=>r.id),include_goals:$('#include-goals').checked});$('#send-preview').innerHTML=`<div class="context"><div class="eyebrow">本轮发送预览</div><h3>确认这些内容再发送</h3><p>你的问题、${r.history_count} 条历史、${r.contexts.length} 份资料。</p><details open><summary>当前问题</summary><pre>${esc(r.message)}</pre></details><details><summary>携带的历史 · ${r.history_count} 条</summary><pre>${esc(list(r.history).map(h=>h.role+'：'+h.text).join('\n\n'))}</pre></details>${r.contexts.map(c=>`<details><summary>${esc(c.title)} · ${esc(c.kind)}</summary><pre>${esc(c.text)}</pre></details>`).join('')}<div class="actions">${btn('确认发送给 Codex','send:'+r.id,'primary')}${btn('返回修改','dismiss-preview','linkbtn')}</div><small>通过当前 Codex 路由处理。</small></div>`;const ctx=$('.chat-context');ctx.open=true;$('#send-preview').scrollIntoView({behavior:'smooth',block:'nearest'})}
else if(cmd==='dismiss-preview')invalidatePreview();
else if(cmd==='send'){const r=await api('/api/chat/send',{preview_id:id});sessionId=r.session_id;localStorage.removeItem('growth-chat-draft');await refresh();toast('已发送，等待 Codex 的实际回复。')}
else if(cmd==='cancel'){await api('/api/chat/cancel',{id});await refresh()}
else if(cmd==='retry'){const j=S.jobs.find(j=>j.id===id);localStorage.setItem('growth-chat-draft',j.message);await draw();toast('原问题已恢复，重新预览后即可发送。')}
else if(cmd==='save-message'){const m=lastMessages.find(m=>m.id===id);noteSeed={body:m.text,kind:'conversation',source:'codex:'+m.job_id,title:'Codex 讨论结论'};noteForm(noteSeed)}
else if(cmd==='record')recordForm(id);
else if(cmd==='save-record'){const common={source_id:recordSource,due:$('#record-due').value};if($('#record-mode').value==='action'){await api('/api/action-from-record',{...common,goal_id:$('#record-goal').value,text:$('#record-title').value,criterion:$('#record-why').value})}else{const did=$('#record-domain').value;await api('/api/goal-from-record',{...common,title:$('#record-title').value,why:$('#record-why').value,domain_id:did,domain:domain(did)?.title||'个人自定',priority:Number($('#record-priority').value),steps:$('#record-steps').value.split('\n').map(x=>x.trim()).filter(Boolean).map(text=>({text,done:false}))})}close();page='goals';await refresh();toast('已经加入计划，并保留了这条原始记录。')}
else if(cmd==='search'){knowledgeQuery=$('#knowledge-query').value;const r=await api('/api/search?q='+encodeURIComponent(knowledgeQuery));$('#search-results').innerHTML=`<div class="row spread"><h2>查到 ${r.results.length} 条相关内容</h2><small>关键词：${esc(knowledgeQuery)}</small></div>`+r.results.map(x=>`<article class="search-result"><div class="row spread"><h3>${esc(x.title)}</h3>${tag((x.collection||'资料')+' · '+(x.status||'可回读'))}</div><p>${esc(x.excerpt)}</p>${btn('回读原文 →','read:'+x.id,'linkbtn')}</article>`).join('')+(r.results.length?'':'<div class="empty">没有匹配这个词。可以缩短关键词，或换一个更具体的说法。</div>')}
}
function toggleRecordMode(){const isAction=$('#record-mode').value==='action';$('#record-existing').hidden=!isAction;$('#record-goal-fields').hidden=isAction}
document.addEventListener('click',async e=>{const n=e.target.closest('[data-page],[data-action]');if(!n)return;e.preventDefault();try{n.disabled=true;if(n.dataset.page)await navigate(n.dataset.page);else await action(n.dataset.action)}catch(err){toast(err.message)}finally{n.disabled=false}});
document.addEventListener('input',e=>{const id=e.target.id;if(id==='capture')localStorage.setItem('growth-draft',e.target.value);if(id==='chat-text'){localStorage.setItem('growth-chat-draft',e.target.value);invalidatePreview()}if(id==='advisor-search'){advisorQuery=e.target.value;$('#advisor-results').innerHTML=advisorTable()}if(id==='learning-position'){$('#position-value').textContent=e.target.value+'%';e.target.dataset.changed='true'}if(e.target.dataset.review){const d=reviewDraft();d[e.target.dataset.review]=e.target.value;d.goal_id=$('#review-goal').value;localStorage.setItem('growth-review-draft',JSON.stringify(d))}});
document.addEventListener('change',async e=>{try{const id=e.target.id;if(id==='category'){advisorCategory=e.target.value;$('#advisor-results').innerHTML=advisorTable()}if(id==='include-goals')invalidatePreview();if(id==='session-select'){sessionId=e.target.value;await draw()}if(id==='record-mode')toggleRecordMode();if(id==='review-goal'){const d=reviewDraft();d.goal_id=e.target.value;localStorage.setItem('growth-review-draft',JSON.stringify(d))}if(e.target.dataset.step){const [gid,sid]=e.target.dataset.step.split(':'),g=structuredClone(S.goals.find(g=>g.id===gid));g.steps.find(s=>s.id===sid).done=e.target.checked;await api('/api/goals',g);await refresh();toast('行动状态已保存；可以在「安排与结果」补充证据。')}}catch(err){toast(err.message);await refresh()}});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&['knowledge-query','context-query'].includes(e.target.id)){e.preventDefault();action(e.target.id==='knowledge-query'?'search':'context-search').catch(err=>toast(err.message))}});
let wasNarrow=window.innerWidth<=760;window.addEventListener('resize',()=>{const narrow=window.innerWidth<=760;if(narrow&&!wasNarrow&&$('.chat-context'))$('.chat-context').open=false;wasNarrow=narrow});
$('#close-modal').onclick=close;
refresh().catch(e=>{$('#view').innerHTML='<section class="panel"><h1>暂时没能读到工作台。</h1><p>请确认本地服务已启动，再刷新页面。浏览器中保存的输入草稿仍然保留。</p></section>';toast(e.message)});
